public static int Find(int[] father, int v){
    int root = v;
    while(father[root] > -1){
        root = father[root];
    }
    return root;
}

public static void Kraskal(){
    ArrayList<Edge> Edges = new ArrayList<>();
    int[] father = new int[C];
    boolean[] linked = new boolean[C];
    for(int i = 0;i < C;i ++){
        linked[i] = false;
    }
    double sum = 0.0;
    for(int i = 0;i < C;i ++){
        father[i] = -1;
    }

    for(int i = 0;i < C;i ++){
        for(int j = i + 1;j < C;j ++){
            if(Lengths[i][j] <= 1000.0 && Lengths[i][j] >= 10.0){
                Edge tmp = new Edge(i, j, Lengths[i][j]);
                Edges.add(tmp);
                linked[i] = true;
                linked[j] = true;
            }
        }
    }

    Edges.sort(new Comparator<Edge>() {
        @Override
        public int compare(Edge e1, Edge e2) {
            double w1 = e1.Getwei();
            double w2 = e2.Getwei();
            if(w1 > w2){
                return 1;
            }
            if(w1 == w2){
                return 0;
            }
            return -1;
        }
    });

    for(int i = 0;i < Edges.size();i ++){
        int rootbeg = Find(father, Edges.get(i).Getbeg());
        int rooted = Find(father, Edges.get(i).Geted());
        if(rootbeg == rooted){
            continue;
        }
        father[rootbeg] = rooted;
        sum += Edges.get(i).Getwei();
    }

    DecimalFormat df = new DecimalFormat("0.0");
    int flag = 0;
    for(int i = 0;i < C;i ++){
        if(!linked[i]){
            flag = 1;
            break;
        }
    }
    if(flag == 1){
        System.out.println("oh!");
    }
    else{
        System.out.println(df.format(sum * 100.0));
    }
}
